import type { FilterForm, FilterValue } from 'models/Filters';

import { buildDefaultDrillDownClearPatch } from '../utils/drillDownBreadcrumbUtils';

export const PERFORMANCE_TOOL_DRILL_DOWN_DIMENSION_KEYS = [
  'growth_levers',
  'beer_price_segment',
  'portfolios',
  'pack_type',
  'global_brands',
  'brands',
  'sub_brands',
] as const;

export type PerformanceToolDrillDownDimensionKey =
  (typeof PERFORMANCE_TOOL_DRILL_DOWN_DIMENSION_KEYS)[number];

export function resolveBrandFilterGroupingAfterClear(
  keptKeys: ReadonlySet<PerformanceToolDrillDownDimensionKey>,
  defaults?: FilterForm,
): FilterValue | undefined {
  if (keptKeys.has('global_brands')) {
    return 'Global Brands';
  }

  if (keptKeys.has('portfolios')) {
    return 'Portfolio';
  }

  if (keptKeys.has('beer_price_segment')) {
    return 'Beer Price Segment';
  }

  if (keptKeys.has('brands') || keptKeys.has('sub_brands')) {
    return 'All Brands';
  }

  return defaults?.brand_filter_groupings ?? null;
}

export function buildPerformanceToolDrillDownClearPatch(
  defaults: FilterForm | undefined,
  keys: readonly PerformanceToolDrillDownDimensionKey[] = PERFORMANCE_TOOL_DRILL_DOWN_DIMENSION_KEYS,
  keptKeys: ReadonlySet<PerformanceToolDrillDownDimensionKey> = new Set(),
): Record<string, FilterValue> {
  const cleared = buildDefaultDrillDownClearPatch(defaults, keys);
  const grouping = resolveBrandFilterGroupingAfterClear(keptKeys, defaults);

  if (grouping !== undefined) {
    cleared.brand_filter_groupings = grouping;
  }

  return cleared;
}
